version.content:
pipeline {
    agent any
    environment {
        // Git 配置 
        GIT_URL = 'http://20.48.1.132:12001/devsecops/opsservice/ansible-playbook.git'
        GIT_BRANCH = 'main'
        GIT_CREDENTIALS_ID = '668d4a76-2bba-4aed-9693-5b6e5625e4a7'

        // AWX 配置（仅部署时触发）
        AWX_URL = 'http://20.12.18.199:8013'
        AWX_WEBHOOK_TOKEN = 'IhDJxIyQvZKaawrdSoDV'
        AWX_JT_ID = '14' //ansible-awx 模版ID
        TARGET_HOST = '20.31.132.40'
        COMPOSE_PATH = '/data/bigdata-sendmsg'

        // 凭据 ID（需要在 Jenkins 中配置）
        SSH_CREDENTIALS_ID = 'ssh-credential-id'   // SSH 私钥凭据
        HARBOR_CREDENTIALS_ID = 'harbor-credential-id'  // Harbor 用户名密码
        MINIO_CREDS = 'c44a58e0-b640-471c-ab76-a667bb5e4fcb'  // 使用在 Jenkins 中配置的凭据ID
        ARTIFACT_BUCKET = 'deploy'   // 定义统一使用的存储桶名称
    }

    stages {
        stage('Show Version') {
            steps {
                // 获取当前构建的唯一数字编号，例如：123
                echo "构建编号是：${env.BUILD_NUMBER}"
                // 获取格式化的构建标签，例如：jenkins-my-app-123
                echo "构建标签是：${env.BUILD_TAG}"
                // 获取用于命名制品的组合ID，例如：123
                echo "构建ID是：${env.BUILD_ID}"
                // 获取任务名称，例如：my-pipeline-job
                echo "任务名称是：${env.JOB_NAME}"
                sh 'printenv'
            }
        }

        stage('代码检出') {
            // when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    echo "检出代码分支: ${env.GIT_BRANCH}"
                    git branch: env.GIT_BRANCH,
                        credentialsId: env.GIT_CREDENTIALS_ID,
                        url: env.GIT_URL
                    // 获取当前 commit ID，用于生成镜像标签
                    sh 'git rev-parse --short HEAD > GIT_COMMIT_SHORT'
                    def gitCommit = readFile('GIT_COMMIT_SHORT').trim()
                    env.GIT_COMMIT_SHORT = gitCommit
                    echo "代码检出完成，Commit: ${env.GIT_COMMIT_SHORT}"
                }
            }
        }
        // stage('Upload Build Artifact') {
        //     steps {
        //         minio(
        //             credentialsId: "${MINIO_CREDS}",
        //             host: 'http://20.12.18.199:8013',
        //             bucket: "${ARTIFACT_BUCKET}",
        //             includes: 'projects/**',
        //             targetFolder: "/"
        //             //targetFolder: "releases/${env.JOB_NAME}/${env.BUILD_NUMBER}",
        //             // pathStyle: true   // ← 关键
        //         )
        //     }
        // }
        stage('Upload Build Artifact-22') {
            steps {
                //mc cp -r projects/ local/${ARTIFACT_BUCKET}/projects/
                sh '''
               mc mirror --overwrite \
          --exclude 'ansible-awx-playbook/**' \
          --exclude '**/gather_full_deployment_info.yml' \
          projects/ local/deploy/projects/
                '''
            }
        }

        stage('触发 AWX 部署') {
            // when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    def payload = """{
                        "event_type": "deploy",
                        "ref": "${env.GIT_BRANCH}",
                        "image": {
                            "registry": "${DOCKER_REGISTRY}",
                            "project": "devops",
                            "name": "${params.APP_NAME}",
                            "tag": "${env.LATEST_IMAGE_TAG}",
                            "full": "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${env.LATEST_IMAGE_TAG}"
                        },
                        "target": {
                            "host": "${TARGET_HOST}",
                            "compose_path": "${COMPOSE_PATH}",
                            "service": "${params.APP_NAME}",
                            "build_id": "${env.BUILD_ID}",
                            "artifact_url": "http://20.12.18.199:8013/artifacts/${ARTIFACT_BUCKET}/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/bigdata-sendmsg-0.0.1-SNAPSHOT.jar",
                            "artifact_name": "bigdata-sendmsg-0.0.1-SNAPSHOT.jar",
                            "bucket_name":"${ARTIFACT_BUCKET}",
                            "object_key":"/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/sendMsg-0.0.1-SNAPSHOT.jar",
                            "app_env_vars": {"NACOS_SERVER": "39.129.77.191:9000"},
                            "java_proxy_host":"172.17.44.8",
                            "java_proxy_port":"7897"
                        }
                    }"""
                    sh """
                        curl -s -X POST \
                            -H "Content-Type: application/json" \
                            -H "X-Custom-Webhook-Token: ${AWX_WEBHOOK_TOKEN}" \
                            -d '${payload}' \
                            ${AWX_URL}/api/v2/job_templates/${AWX_JT_ID}/custom/
                    """
                    echo "AWX 触发完成（异步）"
                }
            }
        }
    }

    post {
        always {
            echo '========================================'
            echo " Pipeline 执行完成 "
            echo " 最终状态: ${currentBuild.result ?: 'SUCCESS'}"
            echo '========================================'
        }
        success {
            echo "✅ 操作成功完成!"
        }
        failure {
            echo "❌ 操作失败，请检查日志!"
        }
    }
}
